INSERT INTO products (id,slug,name,source_name,sku,price_cents,compare_cents,in_stock,product_class,model,caliber,caliber_slug,capacity,barrel_in,generation,optic_cut,summary,title_suffix,client_copy,has_client_copy,attr1_name,attr1_values,attr2_name,attr2_values,primary_image,primary_w,primary_h,primary_variants,image_count) VALUES (4769,'glock-19-gen5-9mm-semi-automatic-pistol','Glock 19 Gen5 9mm Pistol - Compact 15 Round','GLOCK 19 Gen5 9mm Semi Automatic Pistol','GR-4769',59755,76000,1,'Pistol','19','9mm','9mm',NULL,NULL,'Gen 5',NULL,'Glock 19 semi automatic pistol chambered in 9mm. Gen 5.',NULL,'<p>Glock 19 Gen5 9mm compact pistol. Frame without finger grooves, Modular Backstrap System, reversible magazine catch, ambidextrous slide stop lever, Glock Marksman Barrel with recessed crown, nDLC finish, front serrations.</p><ul><li>Caliber: 9x19mm</li><li>System: Safe Action</li><li>Magazine capacity: Standard 15, optional 17 / 24 / 31 / 33</li><li>Barrel length: 102 mm | 4.02 inch</li><li>Overall length: 185 mm | 7.28 inch</li><li>Slide length: 174 mm | 6.85 inch</li><li>Width overall: 34 mm | 1.34 inch</li><li>Slide width: 25.5 mm | 1.00 inch</li><li>Height incl mag: 128 mm | 5.04 inch</li><li>Line of sight: Polymer 153 mm | 6.02 inch, Steel 152 mm | 5.98 inch, GNS 151 mm | 5.94 inch</li><li>Trigger distance: 70 mm | 2.76 inch</li><li>Trigger pull: 26 N | 5.5 lb</li><li>Weight without magazine: 610 g | 21.52 oz</li><li>Weight with empty magazine: 670 g | 23.63 oz</li><li>Weight with loaded magazine: 855 g | 30.16 oz</li></ul><p>Ships with two magazines. Specs from Glock official data for G19 Gen5.</p><p>This Glock 19 for sale is part of current inventory and ships to your pickup location. If you are looking for Glock 19 for sale, this GR-4769 is available.</p>',1,NULL,NULL,NULL,NULL,'4769-0.webp',1320,1320,'400,800',3);
