INSERT INTO products (id,slug,name,source_name,sku,price_cents,compare_cents,in_stock,product_class,model,caliber,caliber_slug,capacity,barrel_in,generation,optic_cut,summary,title_suffix,client_copy,has_client_copy,attr1_name,attr1_values,attr2_name,attr2_values,primary_image,primary_w,primary_h,primary_variants,image_count) VALUES (4806,'glock-42-380-acp-pistol-for-sale-4806','Glock 42 .380 ACP Subcompact - 6 Round','Glock 42 .380 ACP | Pistol For Sale','GR-4806',38855,56905,1,'Pistol','42','.380 ACP','380-acp',NULL,3.26,NULL,NULL,'Glock 42 semi automatic pistol chambered in .380 ACP. 3.26 in barrel.',NULL,'<p>Glock 42 .380 ACP subcompact, first Glock in .380 ACP introduced 2014. Slimline frame, Safe Action, fixed sights with white dot front and white outline rear.</p><ul><li>Caliber: .380 ACP</li><li>System: Safe Action</li><li>Magazine capacity: 6, 6+1 with chamber</li><li>Barrel length: 82.5 mm | 3.25 inch</li><li>Overall length: 151 mm | 5.94 inch</li><li>Slide length: 146 mm | 5.75 inch</li><li>Width: 25 mm | 0.98 inch</li><li>Height incl mag: 105 mm | 4.13 inch</li><li>Line of sight: 125 mm | 4.92 inch</li><li>Weight without magazine: 345 g | 12.17 oz</li><li>Weight with empty magazine: 390 g | 13.76 oz</li><li>Weight with loaded magazine: 450 g | 15.87 oz</li><li>Trigger pull: 24 N | 5.5 lb</li><li>Frame: Polymer, Slide: Steel nDLC</li><li>Accessory rail: No</li></ul><p>Smallest Glock frame for pocket carry. Specs from Glock and distributor data for G42.</p><p>This Glock 42 for sale is part of current inventory and ships to your pickup location. If you are looking for Glock 42 for sale, this GR-4806 is available.</p>',1,NULL,NULL,NULL,NULL,'4806-0.png',546,546,'400',3);
