INSERT INTO products (id,slug,name,source_name,sku,price_cents,compare_cents,in_stock,product_class,model,caliber,caliber_slug,capacity,barrel_in,generation,optic_cut,summary,title_suffix,client_copy,has_client_copy,attr1_name,attr1_values,attr2_name,attr2_values,primary_image,primary_w,primary_h,primary_variants,image_count) VALUES (4937,'glock-45-9mm-pistol-for-sale-4937','Glock 45 Gen5 9mm Crossover - 17 Round','Glock 45 9mm | Pistol For Sale','GR-4937',69255,85405,1,'Pistol','45','9mm','9mm','17+1',4.02,NULL,NULL,'Glock 45 semi automatic pistol chambered in 9mm. 4.02 in barrel, 17+1 capacity.',NULL,'<p>Glock 45 Gen5 9mm crossover pistol. Full size G17 frame with compact G19 slide. Introduced 2018. Flared magwell, front serrations, ambi slide stop, nDLC finish, Glock Marksman Barrel.</p><ul><li>Caliber: 9x19mm</li><li>System: Safe Action</li><li>Magazine capacity: Standard 17, optional 19 / 24 / 31 / 33</li><li>Barrel length: 102 mm | 4.02 inch</li><li>Overall length: 189 mm | 7.44 inch</li><li>Slide length: 174 mm | 6.85 inch</li><li>Width overall: 34 mm | 1.34 inch</li><li>Slide width: 25.5 mm | 1.00 inch</li><li>Height incl mag: 139 mm | 5.47 inch</li><li>Weight without magazine: 616 g | 21.73 oz</li><li>Weight with empty magazine: 694 g | 24.48 oz</li><li>Weight with loaded magazine: 860 g | 30.34 oz</li><li>Trigger pull: 26 N | 5.5 lb</li><li>Finish: nDLC</li></ul><p>Crossover design for duty and carry. Specs from Glock official data for G45 Gen5 FS.</p><p>This Glock 45 for sale is part of current inventory and ships to your pickup location. If you are looking for Glock 45 for sale, this GR-4937 is available.</p>',1,NULL,NULL,NULL,NULL,'4937-0.png',546,546,'400',1);
