INSERT INTO products (id,slug,name,source_name,sku,price_cents,compare_cents,in_stock,product_class,model,caliber,caliber_slug,capacity,barrel_in,generation,optic_cut,summary,title_suffix,client_copy,has_client_copy,attr1_name,attr1_values,attr2_name,attr2_values,primary_image,primary_w,primary_h,primary_variants,image_count) VALUES (4970,'glock-48-mos-9mm-pistol-black-pa4850201rmos','Glock 48 MOS 9mm Slimline - 10 Round','Glock 48 MOS 9mm Pistol, Black - PA4850201RMOS','GR-4970',41705,56905,1,'Pistol','48','9mm','9mm',NULL,NULL,NULL,'MOS','Glock 48 semi automatic pistol chambered in 9mm. MOS.',NULL,'<p>Glock 48 MOS 9mm slimline compact. Full length grip with slim slide, MOS cut for optic, same 3.41 inch barrel as G43X but longer grip. Introduced 2019.</p><ul><li>Caliber: 9x19mm</li><li>System: Safe Action</li><li>Magazine capacity: Standard 10, 10+1 with chamber</li><li>Barrel length: 106 mm | 4.17 inch</li><li>Overall length: 185 mm | 7.28 inch</li><li>Slide length: 174 mm | 6.85 inch</li><li>Width: 28 mm | 1.10 inch</li><li>Height incl mag: 128 mm | 5.04 inch</li><li>Weight without magazine: 524 g | 18.48 oz</li><li>Weight with empty magazine: 580 g | 20.44 oz</li><li>Trigger pull: 26 N | 5.5 lb</li><li>Finish: nDLC</li><li>MOS: Modular Optic System cut</li></ul><p>Slim 10 round carry pistol with longer sight radius than G43. Specs from Glock official data for G48 MOS.</p><p>This Glock 48 for sale is part of current inventory and ships to your pickup location. If you are looking for Glock 48 for sale, this GR-4970 is available.</p>',1,NULL,NULL,NULL,NULL,'4970-0.jpg',546,546,'400',1);
