INSERT INTO products (id,slug,name,source_name,sku,price_cents,compare_cents,in_stock,product_class,model,caliber,caliber_slug,capacity,barrel_in,generation,optic_cut,summary,title_suffix,client_copy,has_client_copy,attr1_name,attr1_values,attr2_name,attr2_values,primary_image,primary_w,primary_h,primary_variants,image_count) VALUES (5110,'glock-43-9mm-pistol-for-sale-5110','Glock 43 9mm Subcompact - 6 Round Slimline','Glock 43 9mm | Pistol For Sale','GR-5110',47405,71155,1,'Pistol','43','9mm','9mm','6+1',3.41,NULL,NULL,'Glock 43 semi automatic pistol chambered in 9mm. 3.41 in barrel, 6+1 capacity.',NULL,'<p>Glock 43 9mm subcompact slimline pistol, single stack. First single stack 9mm introduced 2015. Safe Action system, no accessory rail, beavertail grip extension.</p><ul><li>Caliber: 9x19mm</li><li>System: Safe Action</li><li>Magazine capacity: Standard 6, 6+1 with chamber</li><li>Barrel length: 86.5 mm | 3.41 inch</li><li>Overall length: 159 mm | 6.26 inch</li><li>Slide length: 154 mm | 6.06 inch</li><li>Width: 27 mm | 1.06 inch</li><li>Height incl mag: 108 mm | 4.25 inch</li><li>Trigger distance: 65 mm | 2.56 inch</li><li>Weight without magazine: 460 g | 16.23 oz</li><li>Weight with empty magazine: 510 g | 17.99 oz</li><li>Weight with loaded magazine: 585 g | 20.64 oz</li><li>Trigger pull: 26 N | 5.5 lb</li><li>Sights: Polymer, Steel or GNS</li></ul><p>Slim frame for concealed carry. Specs from Glock official data for G43.</p><p>This Glock 43 for sale is part of current inventory and ships to your pickup location. If you are looking for Glock 43 for sale, this GR-5110 is available.</p>',1,NULL,NULL,NULL,NULL,'5110-0.jpg',546,546,'400',2);
