-- D1 migration for 9mmreloaders catalog
CREATE TABLE categories (
  id INTEGER PRIMARY KEY,
  slug TEXT UNIQUE NOT NULL,
  name TEXT NOT NULL,
  grp TEXT NOT NULL,
  sort INTEGER NOT NULL DEFAULT 100,
  product_count INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE products (
  id INTEGER PRIMARY KEY,
  slug TEXT UNIQUE NOT NULL,
  name TEXT NOT NULL,
  source_name TEXT NOT NULL,
  sku TEXT NOT NULL,
  price_cents INTEGER,
  compare_cents INTEGER,
  in_stock INTEGER NOT NULL DEFAULT 0,
  product_class TEXT NOT NULL,
  model TEXT,
  caliber TEXT,
  caliber_slug TEXT,
  capacity TEXT,
  barrel_in REAL,
  generation TEXT,
  optic_cut TEXT,
  summary TEXT NOT NULL,
  title_suffix TEXT,
  client_copy TEXT,
  has_client_copy INTEGER NOT NULL DEFAULT 0,
  attr1_name TEXT, attr1_values TEXT,
  attr2_name TEXT, attr2_values TEXT,
  primary_image TEXT,
  primary_w INTEGER,
  primary_h INTEGER,
  primary_variants TEXT,
  image_count INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE product_images (
  product_id INTEGER NOT NULL REFERENCES products(id),
  position INTEGER NOT NULL,
  filename TEXT NOT NULL,
  width INTEGER, height INTEGER,
  variants TEXT,
  PRIMARY KEY (product_id, position)
);
CREATE TABLE product_categories (
  product_id INTEGER NOT NULL REFERENCES products(id),
  category_id INTEGER NOT NULL REFERENCES categories(id),
  PRIMARY KEY (product_id, category_id)
);
CREATE TABLE variants (
  id INTEGER PRIMARY KEY,
  product_id INTEGER NOT NULL REFERENCES products(id),
  label TEXT NOT NULL,
  price_cents INTEGER,
  a1_name TEXT, a1_value TEXT, a2_name TEXT, a2_value TEXT
);
